function nurseryTiming(){const chapterEnd=Math.max(fx.depotChapterStart,fx.depotLogoExitStart+fx.depotLogoExitTime+fx.depotBlackHold)+fx.depotChapterAssemble+fx.depotChapterHold+fx.depotChapterDimTime+fx.depotChapterFadeTime,start=Math.max(chapterEnd+Math.max(0,fx.nurseryGap),fx.nurseryStart||0),roomAt=Math.max(.1,fx.nurseryWriteTime)+Math.max(0,fx.nurseryDateHold),passAt=roomAt+Math.max(.1,fx.nurseryRoomTime)+Math.max(0,fx.nurseryMotherHold),cradleAt=passAt+Math.max(.1,fx.nurseryPassTime);return {start,roomAt,passAt,cradleAt,end:start+cradleAt+Math.max(.1,fx.nurseryCradleHold)+Math.max(0,fx.nurseryExitTime)}}
