function repaintNursery(){if(typeof base!=='undefined'){base._renderKey='';frame(base,t)}const note=document.querySelector('#nurseryAssetStatus');if(note){const count=Object.keys(nurserySources).filter(k=>sprites[k]?.naturalWidth).length;note.textContent=count+' / 3 nursery assets ready'+(Object.keys(nurserySources).some(k=>sprites[k]?._loadError)?' · use Reload nursery assets':'')}}
function reloadNurseryAssets(){for(const [key,src]of Object.entries(nurserySources)){sources[key]=src;const im=new Image();im.onload=()=>{im._loadError='';repaintNursery()};im.onerror=()=>{if(!im._retried){im._retried=true;im.src=src+'?v=motion-v70';return}im._loadError=src;repaintNursery()};sprites[key]=im;im.src=src}restoreAssets()}
